function get_portal_i18n($lang_code) {
    $all = get_all_78_i18n();
    if (isset($all[$lang_code])) return $all[$lang_code];
    foreach ($all as $k => $v) {
        if (strtolower($k) === strtolower($lang_code)) return $v;
    }
    return $all['ar'];
}

function map_global_id_to_language($gid) {
    $pos = ($gid - 1) % 2000;
    if ($pos < 800) {
        $t1 = get_tier1_langs();
        return $t1[$pos % 16];
    } elseif ($pos < 1520) {
        $t2 = get_tier2_langs();
        return $t2[($pos - 800) % 30];
    } else {
        $t3 = get_tier3_langs();
        return $t3[($pos - 1520) % 32];
    }
}

function get_first_book_id_for_lang($lang_code) {
    $t1 = get_tier1_langs();
    foreach ($t1 as $i => $l) {
        if (strtolower($l['code']) === strtolower($lang_code)) return $i + 1;
    }
    $t2 = get_tier2_langs();
    foreach ($t2 as $i => $l) {
        if (strtolower($l['code']) === strtolower($lang_code)) return 801 + $i;
    }
    $t3 = get_tier3_langs();
    foreach ($t3 as $i => $l) {
        if (strtolower($l['code']) === strtolower($lang_code)) return 1521 + $i;
    }
    return 1;
}

function make_1m_isbn13($gid, $prefix = "97897") {
    $seq7 = sprintf("%07d", 1000000 + $gid);
    $s12 = $prefix . $seq7;
    $total = 0;
    for ($i = 0; $i < 12; $i++) {
        $digit = intval($s12[$i]);
        $total += $digit * (($i % 2 === 0) ? 1 : 3);
    }
    $check = (10 - ($total % 10)) % 10;
    return $s12 . strval($check);
}

function slugify_en($text) {
    $s = strtolower(trim($text));
    $s = preg_replace('/[^a-z0-9]+/', '-', $s);
    return trim($s, '-');
}

function get_1m_book_metadata($gid) {
    $gid = max(1, min(1000000, intval($gid)));
    $is_paid = ($gid <= 900000);
    $tier_type = $is_paid ? "PAID" : "FREE";
    $batch_number = intval(floor(($gid - 1) / 1000)) + 1;

    $lang = map_global_id_to_language($gid);
    $discs = get_all_100_disciplines();
    $disc = $discs[($gid - 1) % 100];
    $pals = get_palettes_30();
    $pal = $pals[(($gid * 7) + $disc['sector_id'] * 3) % count($pals)];

    if ($is_paid) {
        $prices = get_paid_prices();
        $price_val = $prices[($gid * 11) % count($prices)];
        $price_usd = number_format($price_val, 2, '.', '');
    } else {
        $price_val = 0.00;
        $price_usd = "0.00";
    }

    $isbn13 = make_1m_isbn13($gid);
    $doi = sprintf("10.1007/s1m-nemer.%07d", $gid);
    $sha_seed = hash('sha256', sprintf("ELNEMER-1M-%07d-%s-%s-%s", $gid, $isbn13, $lang['code'], $disc['bisac']));

    $ANGLES_EN = [
        "Mathematical Modeling & High-Dimensional Empirical Frameworks",
        "Algorithmic Architecture & Non-Linear Dynamical Systems",
        "Theoretical Foundations & Scalable Industrial Applications",
        "Stochastic Optimization & Spectral Stability Analysis",
        "Tensor Decomposition & Fault-Tolerant Computing Paradigms",
        "Statistical Inference, Sensitivity Auditing & System Design",
        "Topological Manifolds & Real-Time Signal Processing",
        "Multi-Scale Simulation & Enterprise Architecture Blueprints",
        "Variational Principles & High-Throughput Execution Engines",
        "Axiomatic Formulations & Experimental Verification Protocols"
    ];
    $ANGLES_AR = [
        "النمذجة الرياضية والتحليل التجريبي عالي الأبعاد",
        "البنية الخوارزمية وأنظمة المحاكاة غير الخطية",
        "التأصيل النظري والتطبيقات الصناعية القياسية",
        "التحسين الاستوكاستيكي وتحليل الاستقرار الطيفي",
        "تفكيك المصفوفات الممتدة والأنظمة فائقة الاعتمادية",
        "الاستدلال الإحصائي المتقدم واختبارات الحساسية",
        "طوبولوجيا الفضاءات المركبة ومعالجة الإشارات الفورية",
        "المحاكاة متعددة المقاييس والمخططات الهندسية",
        "المبادئ التغايرية ومحركات التنفيذ فائقة الأداء",
        "الصياغات الأكسيومية وبروتوكولات التحقق المعملي"
    ];

    $angle_idx = intval(floor($gid / 100)) % 10;
    if (in_array($lang['code'], ['ar', 'fa', 'ur'])) {
        $title = "بحوث متقدمة في " . $disc['domain_ar'] . ": " . $ANGLES_AR[$angle_idx];
        $subtitle = "مرجع أكاديمي وعلمي محكم في " . $disc['sector_ar'] . " — تأليف " . $lang['author'];
    } else {
        $title = "Advanced Research in " . $disc['domain_en'] . ": " . $ANGLES_EN[$angle_idx] . " [" . $lang['name'] . "]";
        $subtitle = "Peer-Reviewed Scientific Monograph in " . $disc['sector_en'] . " — By " . $lang['author'];
    }

    $slug = slugify_en($disc['domain_en'] . "-" . $lang['en_name'] . "-vol-" . $gid . "-" . $isbn13);

    return [
        "global_id" => $gid,
        "batch_number" => $batch_number,
        "isbn13" => $isbn13,
        "doi" => $doi,
        "sha256" => $sha_seed,
        "is_paid" => $is_paid,
        "tier_type" => $tier_type,
        "price_usd" => $price_usd,
        "lang_code" => $lang['code'],
        "lang_name" => $lang['name'],
        "lang_en_name" => $lang['en_name'],
        "script" => $lang['script'],
        "author" => $lang['author'],
        "sector_id" => $disc['sector_id'],
        "sector_code" => $disc['sector_code'],
        "sector_ar" => $disc['sector_ar'],
        "sector_en" => $disc['sector_en'],
        "discipline_id" => $disc['discipline_id'],
        "domain_en" => $disc['domain_en'],
        "domain_ar" => $disc['domain_ar'],
        "bisac" => $disc['bisac'],
        "title" => $title,
        "subtitle" => $subtitle,
        "angle_en" => $ANGLES_EN[$angle_idx],
        "angle_ar" => $ANGLES_AR[$angle_idx],
        "pages" => 200,
        "slug" => $slug,
        "palette" => $pal
    ];
}
